// ponytail: in-memory per-process lockout; move to DB/redis if multi-process
const WINDOW_MS = 15 * 60 * 1000
const MAX_FAILURES = 10

const failures = new Map<string, { count: number; windowStart: number }>()

export function isLocked(key: string): boolean {
  const entry = failures.get(key)
  if (!entry) return false
  if (Date.now() - entry.windowStart > WINDOW_MS) {
    failures.delete(key)
    return false
  }
  return entry.count >= MAX_FAILURES
}

export function recordFailure(key: string): void {
  const now = Date.now()
  const entry = failures.get(key)
  if (!entry || now - entry.windowStart > WINDOW_MS) {
    failures.set(key, { count: 1, windowStart: now })
  } else {
    entry.count += 1
  }
}

export function clearFailures(key: string): void {
  failures.delete(key)
}

export function resetLockouts(): void {
  failures.clear()
}

import { randomBytes } from 'node:crypto'
import * as OTPAuth from 'otpauth'
import { and, eq, isNull } from 'drizzle-orm'
import { db } from '../db/client.js'
import { instanceState, mfaBackupCodes, users } from '../db/schema.js'
import { hashToken } from './tokens.js'

const BACKUP_CODE_COUNT = 10

function totpFor(secret: string, email: string): OTPAuth.TOTP {
  return new OTPAuth.TOTP({
    issuer: 'Chapters',
    label: email,
    secret: OTPAuth.Secret.fromBase32(secret),
  })
}

export function generateTotpSecret(): string {
  return new OTPAuth.Secret({ size: 20 }).base32
}

export function provisioningUri(secret: string, email: string): string {
  return totpFor(secret, email).toString()
}

export function verifyTotp(secret: string, email: string, code: string): boolean {
  return totpFor(secret, email).validate({ token: code, window: 1 }) !== null
}

/** Issues fresh backup codes (returned raw exactly once, stored hashed). */
export async function issueBackupCodes(userId: string): Promise<string[]> {
  await db.delete(mfaBackupCodes).where(eq(mfaBackupCodes.userId, userId))
  const codes = Array.from({ length: BACKUP_CODE_COUNT }, () =>
    randomBytes(4).toString('hex'),
  )
  await db
    .insert(mfaBackupCodes)
    .values(codes.map((code) => ({ userId, codeHash: hashToken(code) })))
  return codes
}

/** Consumes a backup code (single-use). True if it was valid and unused. */
export async function consumeBackupCode(userId: string, code: string): Promise<boolean> {
  const updated = await db
    .update(mfaBackupCodes)
    .set({ usedAt: new Date() })
    .where(
      and(
        eq(mfaBackupCodes.userId, userId),
        eq(mfaBackupCodes.codeHash, hashToken(code)),
        isNull(mfaBackupCodes.usedAt),
      ),
    )
    .returning({ id: mfaBackupCodes.id })
  return updated.length > 0
}

/** Validates a TOTP code or, failing that, a single-use backup code. */
export async function verifyMfaCode(
  user: { id: string; email: string; totpSecret: string | null },
  code: string,
): Promise<boolean> {
  if (!user.totpSecret) return false
  if (verifyTotp(user.totpSecret, user.email, code)) return true
  return consumeBackupCode(user.id, code)
}

export async function instanceRequiresMfa(): Promise<boolean> {
  const state = (await db.select().from(instanceState).limit(1))[0]
  return Boolean(state?.requireMfa)
}

export async function setInstanceMfaRequirement(required: boolean): Promise<void> {
  await db.update(instanceState).set({ requireMfa: required })
}

export type MfaUser = typeof users.$inferSelect

import type { FastifyInstance } from 'fastify'
import { eq } from 'drizzle-orm'
import { db } from '../db/client.js'
import { users } from '../db/schema.js'
import { logSecurityEvent } from './security-events.js'
import {
  generateTotpSecret,
  instanceRequiresMfa,
  issueBackupCodes,
  provisioningUri,
  verifyMfaCode,
  verifyTotp,
} from './mfa.js'

const codeBody = {
  type: 'object',
  required: ['code'],
  properties: { code: { type: 'string', minLength: 6, maxLength: 16 } },
} as const

export function mfaRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAuth)

  /** Step 1: provision a pending secret (not active until verified). */
  app.post('/mfa/setup', async (req) => {
    const secret = generateTotpSecret()
    await db
      .update(users)
      .set({ totpSecret: secret, mfaEnabledAt: null })
      .where(eq(users.id, req.user!.id))
    return { secret, uri: provisioningUri(secret, req.user!.email) }
  })

  /** Step 2: prove the authenticator works; backup codes shown once. */
  app.post<{ Body: { code: string } }>(
    '/mfa/enable',
    { schema: { body: codeBody } },
    async (req, reply) => {
      const user = (await db.select().from(users).where(eq(users.id, req.user!.id)))[0]!
      if (!user.totpSecret || user.mfaEnabledAt) {
        return reply.code(400).send({ error: 'no pending MFA setup' })
      }
      if (!verifyTotp(user.totpSecret, user.email, req.body.code)) {
        return reply.code(400).send({ error: 'invalid code' })
      }
      await db.update(users).set({ mfaEnabledAt: new Date() }).where(eq(users.id, user.id))
      const backupCodes = await issueBackupCodes(user.id)
      await logSecurityEvent({ type: 'mfa_enabled', subjectUserId: user.id })
      return { status: 'enabled', backupCodes }
    },
  )

  app.post<{ Body: { code: string } }>(
    '/mfa/disable',
    { schema: { body: codeBody } },
    async (req, reply) => {
      const user = (await db.select().from(users).where(eq(users.id, req.user!.id)))[0]!
      if (!user.mfaEnabledAt) return reply.code(400).send({ error: 'MFA is not enabled' })
      if (await instanceRequiresMfa()) {
        return reply.code(403).send({ error: 'MFA is required on this instance' })
      }
      if (!(await verifyMfaCode(user, req.body.code))) {
        return reply.code(400).send({ error: 'invalid code' })
      }
      await db
        .update(users)
        .set({ totpSecret: null, mfaEnabledAt: null })
        .where(eq(users.id, user.id))
      await logSecurityEvent({ type: 'mfa_disabled', subjectUserId: user.id })
      return { status: 'disabled' }
    },
  )
}

import type { FastifyInstance } from 'fastify'
import { and, eq } from 'drizzle-orm'
import { db } from '../db/client.js'
import { teamMemberships, users, vaults, vaultShares } from '../db/schema.js'
import { destroyUserSessions } from './sessions.js'
import { logSecurityEvent } from './security-events.js'
import { notify } from '../notifications/notify.js'
import { emitPermissionChange } from '../sync/permission-events.js'

export function adminRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAdmin)

  app.get<{ Querystring: { status?: 'pending_approval' | 'active' | 'deactivated' } }>(
    '/users',
    async (req) => {
      const base = db
        .select({
          id: users.id,
          email: users.email,
          status: users.status,
          role: users.role,
          createdAt: users.createdAt,
        })
        .from(users)
      const rows = req.query.status
        ? await base.where(eq(users.status, req.query.status))
        : await base
      return rows
    },
  )

  app.post<{ Params: { id: string } }>('/users/:id/approve', async (req, reply) => {
    const [user] = await db
      .update(users)
      .set({ status: 'active' })
      .where(and(eq(users.id, req.params.id), eq(users.status, 'pending_approval')))
      .returning()
    if (!user) return reply.code(404).send({ error: 'no pending user' })
    await logSecurityEvent({
      type: 'user_approved',
      actorUserId: req.user!.id,
      subjectUserId: user.id,
    })
    await notify({
      recipientId: user.id,
      type: 'signup_approved',
      message: 'Your Chapters account has been approved. You can now log in.',
    })
    return { status: 'active' }
  })

  app.post<{ Params: { id: string } }>('/users/:id/promote', async (req, reply) => {
    const [user] = await db
      .update(users)
      .set({ role: 'admin' })
      .where(eq(users.id, req.params.id))
      .returning()
    if (!user) return reply.code(404).send({ error: 'user not found' })
    await logSecurityEvent({
      type: 'admin_promoted',
      actorUserId: req.user!.id,
      subjectUserId: user.id,
    })
    return { role: 'admin' }
  })

  app.post<{ Params: { id: string } }>('/users/:id/deactivate', async (req, reply) => {
    const [user] = await db
      .update(users)
      .set({ status: 'deactivated' })
      .where(eq(users.id, req.params.id))
      .returning()
    if (!user) return reply.code(404).send({ error: 'user not found' })
    // Cascade cleanup per spec hardening: sessions, memberships, direct shares.
    await destroyUserSessions(user.id)
    await db.delete(teamMemberships).where(eq(teamMemberships.userId, user.id))
    await db
      .delete(vaultShares)
      .where(and(eq(vaultShares.granteeType, 'user'), eq(vaultShares.granteeId, user.id)))
    await logSecurityEvent({
      type: 'user_deactivated',
      actorUserId: req.user!.id,
      subjectUserId: user.id,
    })
    emitPermissionChange({ userIds: [user.id] })
    await notify({
      recipientId: user.id,
      type: 'account_status_changed',
      message: 'Your Chapters account has been deactivated by an admin.',
    })
    return { status: 'deactivated' }
  })

  app.post<{ Params: { id: string }; Body: { newOwnerId: string } }>(
    '/vaults/:id/transfer-owner',
    {
      schema: {
        body: {
          type: 'object',
          required: ['newOwnerId'],
          properties: { newOwnerId: { type: 'string', format: 'uuid' } },
        },
      },
    },
    async (req, reply) => {
      const newOwner = (
        await db.select().from(users).where(eq(users.id, req.body.newOwnerId))
      )[0]
      if (!newOwner || newOwner.status !== 'active') {
        return reply.code(400).send({ error: 'new owner must be an active user' })
      }
      const [vault] = await db
        .update(vaults)
        .set({ ownerId: newOwner.id })
        .where(eq(vaults.id, req.params.id))
        .returning()
      if (!vault) return reply.code(404).send({ error: 'vault not found' })
      await logSecurityEvent({
        type: 'vault_ownership_transferred',
        actorUserId: req.user!.id,
        subjectUserId: newOwner.id,
        detail: { vaultId: vault.id },
      })
      await notify({
        recipientId: newOwner.id,
        type: 'vault_shared',
        entityType: 'vault',
        entityId: vault.id,
        message: `You are now the owner of vault "${vault.name}".`,
      })
      return { ownerId: newOwner.id }
    },
  )
}

import type { FastifyInstance } from 'fastify'
import { and, count, desc, eq, isNull, sql, sum } from 'drizzle-orm'
import { db } from '../db/client.js'
import {
  mcpConnections,
  noteRevisions,
  notes,
  securityEvents,
  teamMemberships,
  teams,
  users,
  vaults,
  vaultShares,
} from '../db/schema.js'
import { logSecurityEvent } from './security-events.js'
import { emitPermissionChange } from '../sync/permission-events.js'
import { setInstanceMfaRequirement } from './mfa.js'

/**
 * Admin oversight dashboard (spec): metadata only, never note content —
 * no endpoint here returns a note's text, frontmatter values, or
 * revision bodies. Force-revoke is a structural/access action.
 */
export function adminDashboardRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAdmin)

  app.get('/stats', async () => {
    const usersByStatus = await db
      .select({ status: users.status, count: count() })
      .from(users)
      .groupBy(users.status)
    const [vaultCount] = await db.select({ count: count() }).from(vaults)
    const [teamCount] = await db.select({ count: count() }).from(teams)
    const [noteCount] = await db
      .select({ count: count() })
      .from(notes)
      .where(isNull(notes.deletedAt))
    // ponytail: storage = text length of live notes, not real size-on-disk
    const [storage] = await db
      .select({ bytes: sum(sql<number>`length(${notes.body}) + length(${notes.frontmatter}::text)`) })
      .from(notes)
      .where(isNull(notes.deletedAt))
    const [activeMcp] = await db
      .select({ count: count() })
      .from(mcpConnections)
      .where(isNull(mcpConnections.revokedAt))
    return {
      usersByStatus,
      vaults: vaultCount!.count,
      teams: teamCount!.count,
      notes: noteCount!.count,
      storageBytes: Number(storage!.bytes ?? 0),
      activeMcpConnections: activeMcp!.count,
    }
  })

  app.get('/vaults', async () => {
    const rows = await db
      .select({
        id: vaults.id,
        name: vaults.name,
        ownerEmail: users.email,
        mergeable: vaults.mergeable,
        noteCount: count(notes.id),
        lastActivity: sql<string | null>`max(${notes.updatedAt})`,
      })
      .from(vaults)
      .innerJoin(users, eq(users.id, vaults.ownerId))
      .leftJoin(notes, and(eq(notes.vaultId, vaults.id), isNull(notes.deletedAt)))
      .groupBy(vaults.id, users.email)
    const shares = await db
      .select({ vaultId: vaultShares.vaultId, count: count() })
      .from(vaultShares)
      .groupBy(vaultShares.vaultId)
    const shareCounts = new Map(shares.map((s) => [s.vaultId, s.count]))
    return rows.map((r) => ({ ...r, shareCount: shareCounts.get(r.id) ?? 0 }))
  })

  app.get('/teams', async () => {
    return db
      .select({ id: teams.id, name: teams.name, memberCount: count(teamMemberships.userId) })
      .from(teams)
      .leftJoin(teamMemberships, eq(teamMemberships.teamId, teams.id))
      .groupBy(teams.id)
  })

  app.get<{ Querystring: { limit?: number; offset?: number } }>(
    '/security-events',
    {
      schema: {
        querystring: {
          type: 'object',
          properties: {
            limit: { type: 'integer', minimum: 1, maximum: 200, default: 50 },
            offset: { type: 'integer', minimum: 0, default: 0 },
          },
        },
      },
    },
    async (req) => {
      return db
        .select()
        .from(securityEvents)
        .orderBy(desc(securityEvents.createdAt))
        .limit(req.query.limit ?? 50)
        .offset(req.query.offset ?? 0)
    },
  )

  app.get<{ Querystring: { limit?: number; offset?: number } }>(
    '/audit-trail',
    {
      schema: {
        querystring: {
          type: 'object',
          properties: {
            limit: { type: 'integer', minimum: 1, maximum: 200, default: 50 },
            offset: { type: 'integer', minimum: 0, default: 0 },
          },
        },
      },
    },
    async (req) => {
      // Who/what changed which note, when — never the content itself.
      return db
        .select({
          id: noteRevisions.id,
          notePath: notes.path,
          vaultId: notes.vaultId,
          actorType: noteRevisions.actorType,
          actorId: noteRevisions.actorId,
          action: noteRevisions.action,
          createdAt: noteRevisions.createdAt,
        })
        .from(noteRevisions)
        .innerJoin(notes, eq(notes.id, noteRevisions.noteId))
        .orderBy(desc(noteRevisions.createdAt))
        .limit(req.query.limit ?? 50)
        .offset(req.query.offset ?? 0)
    },
  )

  app.get('/shares', async () => {
    return db.select().from(vaultShares)
  })

  // Incident-response lever: structural revocation, instance-wide.
  app.delete<{ Params: { shareId: string } }>('/shares/:shareId', async (req, reply) => {
    const [share] = await db
      .delete(vaultShares)
      .where(eq(vaultShares.id, req.params.shareId))
      .returning()
    if (!share) return reply.code(404).send({ error: 'share not found' })
    await logSecurityEvent({
      type: 'admin_force_revoked_share',
      actorUserId: req.user!.id,
      detail: { shareId: share.id, vaultId: share.vaultId },
    })
    emitPermissionChange({ vaultIds: [share.vaultId] })
    return { status: 'revoked' }
  })

  app.post<{ Params: { id: string } }>('/mcp-connections/:id/revoke', async (req, reply) => {
    const [connection] = await db
      .update(mcpConnections)
      .set({ revokedAt: new Date() })
      .where(and(eq(mcpConnections.id, req.params.id), isNull(mcpConnections.revokedAt)))
      .returning()
    if (!connection) return reply.code(404).send({ error: 'connection not found' })
    await logSecurityEvent({
      type: 'admin_force_revoked_mcp_connection',
      actorUserId: req.user!.id,
      mcpConnectionId: connection.id,
      subjectUserId: connection.userId,
    })
    return { status: 'revoked' }
  })

  app.put<{ Body: { required: boolean } }>(
    '/mfa-requirement',
    {
      schema: {
        body: {
          type: 'object',
          required: ['required'],
          properties: { required: { type: 'boolean' } },
        },
      },
    },
    async (req) => {
      await setInstanceMfaRequirement(req.body.required)
      await logSecurityEvent({
        type: 'mfa_requirement_changed',
        actorUserId: req.user!.id,
        detail: { required: req.body.required },
      })
      return { required: req.body.required }
    },
  )
}

