import fp from 'fastify-plugin'
import type { FastifyReply, FastifyRequest } from 'fastify'
import { getSessionUser, type SessionUser } from './sessions.js'
import { logSecurityEvent } from './security-events.js'
import { instanceRequiresMfa } from './mfa.js'

declare module 'fastify' {
  interface FastifyRequest {
    user: SessionUser | null
    sessionToken: string | null
  }
  interface FastifyInstance {
    requireAuth: (req: FastifyRequest, reply: FastifyReply) => Promise<void>
    requireAdmin: (req: FastifyRequest, reply: FastifyReply) => Promise<void>
  }
}

export const SESSION_COOKIE = 'sid'

export const authPlugin = fp(async (app) => {
  app.decorateRequest('user', null)
  app.decorateRequest('sessionToken', null)

  app.addHook('onRequest', async (req) => {
    const token = req.cookies[SESSION_COOKIE]
    if (token) {
      req.sessionToken = token
      req.user = await getSessionUser(token)
    }
  })

  const MFA_EXEMPT = ['/api/mfa', '/api/logout', '/api/me']

  app.decorate('requireAuth', async (req: FastifyRequest, reply: FastifyReply) => {
    if (!req.user) {
      await reply.code(401).send({ error: 'authentication required' })
      return
    }
    // Admin-mandated MFA: users without TOTP may only reach the setup
    // surface until they enable it (MFA spec enforcement rule).
    if (!req.user.mfaEnabledAt && !MFA_EXEMPT.some((p) => req.url.startsWith(p))) {
      if (await instanceRequiresMfa()) {
        await reply.code(403).send({ error: 'MFA setup required', mfaSetupRequired: true })
      }
    }
  })

  app.decorate('requireAdmin', async (req: FastifyRequest, reply: FastifyReply) => {
    if (!req.user) {
      await reply.code(401).send({ error: 'authentication required' })
      return
    }
    if (req.user.role !== 'admin') {
      await logSecurityEvent({
        type: 'permission_denied',
        actorUserId: req.user.id,
        ip: req.ip,
        detail: { route: req.url },
      })
      await reply.code(403).send({ error: 'admin required' })
    }
  })
})

import { db } from '../db/client.js'
import { securityEvents } from '../db/schema.js'

export async function logSecurityEvent(event: {
  type: string
  actorUserId?: string
  subjectUserId?: string
  mcpConnectionId?: string
  ip?: string
  detail?: unknown
}): Promise<void> {
  await db.insert(securityEvents).values(event)
}

import type { FastifyInstance } from 'fastify'
import { and, eq, inArray } from 'drizzle-orm'
import { db } from '../db/client.js'
import {
  teamMemberships,
  teams,
  users,
  vaultGraphPreferences,
  vaults,
  vaultShares,
} from '../db/schema.js'
import { logSecurityEvent } from '../auth/security-events.js'
import { notify } from '../notifications/notify.js'
import { listAccessibleVaults, resolveAccess } from './permissions.js'
import { emitPermissionChange } from '../sync/permission-events.js'

async function requireOwner(userId: string, vaultId: string) {
  const access = await resolveAccess(userId, vaultId)
  return access === 'owner'
}

export function vaultRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAuth)

  app.post<{ Body: { name: string } }>(
    '/vaults',
    {
      schema: {
        body: {
          type: 'object',
          required: ['name'],
          properties: { name: { type: 'string', minLength: 1, maxLength: 200 } },
        },
      },
    },
    async (req) => {
      const [vault] = await db
        .insert(vaults)
        .values({ name: req.body.name, ownerId: req.user!.id })
        .returning()
      return vault
    },
  )

  app.get('/vaults', async (req) => listAccessibleVaults(req.user!.id))

  app.get<{ Params: { id: string } }>('/vaults/:id/access', async (req, reply) => {
    const access = await resolveAccess(req.user!.id, req.params.id)
    if (!access) return reply.code(404).send({ error: 'not found' })
    return { access }
  })

  app.patch<{ Params: { id: string }; Body: { name?: string; mergeable?: boolean } }>(
    '/vaults/:id',
    {
      schema: {
        body: {
          type: 'object',
          properties: {
            name: { type: 'string', minLength: 1, maxLength: 200 },
            mergeable: { type: 'boolean' },
          },
        },
      },
    },
    async (req, reply) => {
      if (!(await requireOwner(req.user!.id, req.params.id))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const [vault] = await db
        .update(vaults)
        .set(req.body)
        .where(eq(vaults.id, req.params.id))
        .returning()
      return vault
    },
  )

  app.post<{
    Params: { id: string }
    Body: { granteeType: 'user' | 'team'; granteeId: string; permission: 'read' | 'edit' }
  }>(
    '/vaults/:id/shares',
    {
      schema: {
        body: {
          type: 'object',
          required: ['granteeType', 'granteeId', 'permission'],
          properties: {
            granteeType: { enum: ['user', 'team'] },
            granteeId: { type: 'string', format: 'uuid' },
            permission: { enum: ['read', 'edit'] },
          },
        },
      },
    },
    async (req, reply) => {
      const vaultId = req.params.id
      if (!(await requireOwner(req.user!.id, vaultId))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const { granteeType, granteeId, permission } = req.body
      if (granteeType === 'user') {
        const grantee = (await db.select().from(users).where(eq(users.id, granteeId)))[0]
        if (!grantee || grantee.status !== 'active') {
          return reply.code(400).send({ error: 'grantee must be an active user' })
        }
      } else {
        const team = (await db.select().from(teams).where(eq(teams.id, granteeId)))[0]
        if (!team) return reply.code(400).send({ error: 'team not found' })
      }
      const [share] = await db
        .insert(vaultShares)
        .values({ vaultId, granteeType, granteeId, permission })
        .onConflictDoUpdate({
          target: [vaultShares.vaultId, vaultShares.granteeType, vaultShares.granteeId],
          set: { permission },
        })
        .returning()
      const vault = (await db.select().from(vaults).where(eq(vaults.id, vaultId)))[0]!
      const recipients =
        granteeType === 'user'
          ? [granteeId]
          : (
              await db
                .select({ userId: teamMemberships.userId })
                .from(teamMemberships)
                .where(eq(teamMemberships.teamId, granteeId))
            ).map((m) => m.userId)
      for (const recipientId of recipients) {
        if (recipientId === req.user!.id) continue
        await notify({
          recipientId,
          type: 'vault_shared',
          entityType: 'vault',
          entityId: vaultId,
          message: `Vault "${vault.name}" was shared with you (${permission}).`,
        })
      }
      await logSecurityEvent({
        type: 'vault_share_created',
        actorUserId: req.user!.id,
        detail: { vaultId, granteeType, granteeId, permission },
      })
      emitPermissionChange({ vaultIds: [vaultId] })
      return share
    },
  )

  app.get<{ Params: { id: string } }>('/vaults/:id/shares', async (req, reply) => {
    const vaultId = req.params.id
    if (!(await requireOwner(req.user!.id, vaultId))) {
      return reply.code(404).send({ error: 'not found' })
    }
    const shares = await db.select().from(vaultShares).where(eq(vaultShares.vaultId, vaultId))
    // Hardening: expand team shares to the current member list so the
    // owner sees exactly who has access right now, not just the grant.
    const teamIds = shares.filter((s) => s.granteeType === 'team').map((s) => s.granteeId)
    const members = teamIds.length
      ? await db
          .select({
            teamId: teamMemberships.teamId,
            userId: teamMemberships.userId,
            email: users.email,
          })
          .from(teamMemberships)
          .innerJoin(users, eq(users.id, teamMemberships.userId))
          .where(inArray(teamMemberships.teamId, teamIds))
      : []
    return shares.map((s) => ({
      ...s,
      members: s.granteeType === 'team' ? members.filter((m) => m.teamId === s.granteeId) : undefined,
    }))
  })

  app.delete<{ Params: { id: string; shareId: string } }>(
    '/vaults/:id/shares/:shareId',
    async (req, reply) => {
      const vaultId = req.params.id
      if (!(await requireOwner(req.user!.id, vaultId))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const [share] = await db
        .delete(vaultShares)
        .where(and(eq(vaultShares.id, req.params.shareId), eq(vaultShares.vaultId, vaultId)))
        .returning()
      if (!share) return reply.code(404).send({ error: 'share not found' })
      const vault = (await db.select().from(vaults).where(eq(vaults.id, vaultId)))[0]!
      if (share.granteeType === 'user') {
        await notify({
          recipientId: share.granteeId,
          type: 'vault_share_revoked',
          entityType: 'vault',
          entityId: vaultId,
          message: `Your access to vault "${vault.name}" was revoked.`,
        })
      }
      await logSecurityEvent({
        type: 'vault_share_revoked',
        actorUserId: req.user!.id,
        detail: { vaultId, shareId: share.id },
      })
      emitPermissionChange({ vaultIds: [vaultId] })
      return { status: 'revoked' }
    },
  )

  app.post<{ Params: { id: string }; Body: { newOwnerId: string } }>(
    '/vaults/:id/transfer',
    {
      schema: {
        body: {
          type: 'object',
          required: ['newOwnerId'],
          properties: { newOwnerId: { type: 'string', format: 'uuid' } },
        },
      },
    },
    async (req, reply) => {
      if (!(await requireOwner(req.user!.id, req.params.id))) {
        return reply.code(404).send({ error: 'not found' })
      }
      const newOwner = (
        await db.select().from(users).where(eq(users.id, req.body.newOwnerId))
      )[0]
      if (!newOwner || newOwner.status !== 'active') {
        return reply.code(400).send({ error: 'new owner must be an active user' })
      }
      const [vault] = await db
        .update(vaults)
        .set({ ownerId: newOwner.id })
        .where(eq(vaults.id, req.params.id))
        .returning()
      await logSecurityEvent({
        type: 'vault_ownership_transferred',
        actorUserId: req.user!.id,
        subjectUserId: newOwner.id,
        detail: { vaultId: vault!.id },
      })
      emitPermissionChange({ vaultIds: [vault!.id] })
      return { ownerId: newOwner.id }
    },
  )

  app.put<{ Params: { id: string }; Body: { include: boolean } }>(
    '/vaults/:id/graph-preference',
    {
      schema: {
        body: {
          type: 'object',
          required: ['include'],
          properties: { include: { type: 'boolean' } },
        },
      },
    },
    async (req, reply) => {
      // Hardening: setting a preference requires current access — the
      // toggle must not be usable to probe vault IDs.
      const access = await resolveAccess(req.user!.id, req.params.id)
      if (!access) return reply.code(404).send({ error: 'not found' })
      await db
        .insert(vaultGraphPreferences)
        .values({ userId: req.user!.id, vaultId: req.params.id, include: req.body.include })
        .onConflictDoUpdate({
          target: [vaultGraphPreferences.userId, vaultGraphPreferences.vaultId],
          set: { include: req.body.include },
        })
      return { include: req.body.include }
    },
  )
}

import { and, eq } from 'drizzle-orm'
import { db } from '../db/client.js'
import { teamMemberships, users, vaults, vaultShares } from '../db/schema.js'

export type Access = 'owner' | 'edit' | 'read'

const RANK: Record<Access, number> = { read: 1, edit: 2, owner: 3 }

export function atLeast(access: Access | null, needed: Access): boolean {
  return access !== null && RANK[access] >= RANK[needed]
}

/**
 * The access resolution rule (sub-project 1 spec): own it, direct share,
 * or team share — highest permission wins. Always resolved live; callers
 * must never cache the result across requests. Only active users have
 * any access at all.
 */
export async function resolveAccess(
  userId: string,
  vaultId: string,
): Promise<Access | null> {
  const user = (
    await db.select({ status: users.status }).from(users).where(eq(users.id, userId))
  )[0]
  if (user?.status !== 'active') return null

  const vault = (
    await db.select({ ownerId: vaults.ownerId }).from(vaults).where(eq(vaults.id, vaultId))
  )[0]
  if (!vault) return null
  if (vault.ownerId === userId) return 'owner'

  const direct = await db
    .select({ permission: vaultShares.permission })
    .from(vaultShares)
    .where(
      and(
        eq(vaultShares.vaultId, vaultId),
        eq(vaultShares.granteeType, 'user'),
        eq(vaultShares.granteeId, userId),
      ),
    )

  const viaTeam = await db
    .select({ permission: vaultShares.permission })
    .from(vaultShares)
    .innerJoin(teamMemberships, eq(teamMemberships.teamId, vaultShares.granteeId))
    .where(
      and(
        eq(vaultShares.vaultId, vaultId),
        eq(vaultShares.granteeType, 'team'),
        eq(teamMemberships.userId, userId),
      ),
    )

  const grants = [...direct, ...viaTeam].map((g) => g.permission)
  if (grants.includes('edit')) return 'edit'
  if (grants.includes('read')) return 'read'
  return null
}

/** Every vault the user can currently reach, with their effective access. */
export async function listAccessibleVaults(
  userId: string,
): Promise<Array<{ id: string; name: string; ownerId: string; mergeable: boolean; access: Access }>> {
  const user = (
    await db.select({ status: users.status }).from(users).where(eq(users.id, userId))
  )[0]
  if (user?.status !== 'active') return []

  const owned = await db.select().from(vaults).where(eq(vaults.ownerId, userId))

  const direct = await db
    .select({ vault: vaults, permission: vaultShares.permission })
    .from(vaultShares)
    .innerJoin(vaults, eq(vaults.id, vaultShares.vaultId))
    .where(and(eq(vaultShares.granteeType, 'user'), eq(vaultShares.granteeId, userId)))

  const viaTeam = await db
    .select({ vault: vaults, permission: vaultShares.permission })
    .from(vaultShares)
    .innerJoin(vaults, eq(vaults.id, vaultShares.vaultId))
    .innerJoin(teamMemberships, eq(teamMemberships.teamId, vaultShares.granteeId))
    .where(and(eq(vaultShares.granteeType, 'team'), eq(teamMemberships.userId, userId)))

  const byId = new Map<string, { id: string; name: string; ownerId: string; mergeable: boolean; access: Access }>()
  for (const v of owned) {
    byId.set(v.id, { id: v.id, name: v.name, ownerId: v.ownerId, mergeable: v.mergeable, access: 'owner' })
  }
  for (const { vault, permission } of [...direct, ...viaTeam]) {
    const existing = byId.get(vault.id)
    if (existing && RANK[existing.access] >= RANK[permission]) continue
    byId.set(vault.id, {
      id: vault.id,
      name: vault.name,
      ownerId: vault.ownerId,
      mergeable: vault.mergeable,
      access: permission,
    })
  }
  return [...byId.values()]
}

/** Every user who can currently reach the vault (owner, direct, via team). */
export async function listUsersWithAccess(vaultId: string): Promise<string[]> {
  const vault = (
    await db.select({ ownerId: vaults.ownerId }).from(vaults).where(eq(vaults.id, vaultId))
  )[0]
  if (!vault) return []
  const direct = await db
    .select({ userId: vaultShares.granteeId })
    .from(vaultShares)
    .where(and(eq(vaultShares.vaultId, vaultId), eq(vaultShares.granteeType, 'user')))
  const viaTeam = await db
    .select({ userId: teamMemberships.userId })
    .from(vaultShares)
    .innerJoin(teamMemberships, eq(teamMemberships.teamId, vaultShares.granteeId))
    .where(and(eq(vaultShares.vaultId, vaultId), eq(vaultShares.granteeType, 'team')))
  return [...new Set([vault.ownerId, ...direct.map((d) => d.userId), ...viaTeam.map((t) => t.userId)])]
}

import type { FastifyInstance } from 'fastify'
import { and, eq } from 'drizzle-orm'
import { db } from '../db/client.js'
import { teamMemberships, teams, users, vaults, vaultShares } from '../db/schema.js'
import { notify } from '../notifications/notify.js'
import { emitPermissionChange } from '../sync/permission-events.js'

async function isTeamOwner(userId: string, teamId: string): Promise<boolean> {
  const row = (
    await db
      .select()
      .from(teamMemberships)
      .where(
        and(
          eq(teamMemberships.teamId, teamId),
          eq(teamMemberships.userId, userId),
          eq(teamMemberships.role, 'owner'),
        ),
      )
  )[0]
  return Boolean(row)
}

/**
 * Hardening (sub-project 1): when a team's membership changes, notify the
 * owners of every vault currently shared with that team.
 */
async function notifyVaultOwnersOfMembershipChange(
  teamId: string,
  message: string,
): Promise<void> {
  const affected = await db
    .select({ ownerId: vaults.ownerId, vaultName: vaults.name })
    .from(vaultShares)
    .innerJoin(vaults, eq(vaults.id, vaultShares.vaultId))
    .where(and(eq(vaultShares.granteeType, 'team'), eq(vaultShares.granteeId, teamId)))
  for (const { ownerId, vaultName } of affected) {
    await notify({
      recipientId: ownerId,
      type: 'team_membership_changed',
      entityType: 'team',
      entityId: teamId,
      message: `${message} (team has access to your vault "${vaultName}").`,
    })
  }
}

export function teamRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAuth)

  app.post<{ Body: { name: string } }>(
    '/teams',
    {
      schema: {
        body: {
          type: 'object',
          required: ['name'],
          properties: { name: { type: 'string', minLength: 1, maxLength: 200 } },
        },
      },
    },
    async (req) => {
      const [team] = await db.insert(teams).values({ name: req.body.name }).returning()
      await db
        .insert(teamMemberships)
        .values({ teamId: team!.id, userId: req.user!.id, role: 'owner' })
      return team
    },
  )

  app.get('/teams', async (req) => {
    return db
      .select({ id: teams.id, name: teams.name, role: teamMemberships.role })
      .from(teamMemberships)
      .innerJoin(teams, eq(teams.id, teamMemberships.teamId))
      .where(eq(teamMemberships.userId, req.user!.id))
  })

  app.get<{ Params: { id: string } }>('/teams/:id/members', async (req, reply) => {
    const membership = (
      await db
        .select()
        .from(teamMemberships)
        .where(
          and(eq(teamMemberships.teamId, req.params.id), eq(teamMemberships.userId, req.user!.id)),
        )
    )[0]
    if (!membership) return reply.code(404).send({ error: 'not found' })
    return db
      .select({ userId: users.id, email: users.email, role: teamMemberships.role })
      .from(teamMemberships)
      .innerJoin(users, eq(users.id, teamMemberships.userId))
      .where(eq(teamMemberships.teamId, req.params.id))
  })

  app.post<{ Params: { id: string }; Body: { userId: string } }>(
    '/teams/:id/members',
    {
      schema: {
        body: {
          type: 'object',
          required: ['userId'],
          properties: { userId: { type: 'string', format: 'uuid' } },
        },
      },
    },
    async (req, reply) => {
      if (!(await isTeamOwner(req.user!.id, req.params.id))) {
        return reply.code(403).send({ error: 'team owner required' })
      }
      const member = (await db.select().from(users).where(eq(users.id, req.body.userId)))[0]
      if (!member || member.status !== 'active') {
        return reply.code(400).send({ error: 'user must be active' })
      }
      await db
        .insert(teamMemberships)
        .values({ teamId: req.params.id, userId: member.id })
        .onConflictDoNothing()
      const team = (await db.select().from(teams).where(eq(teams.id, req.params.id)))[0]!
      await notify({
        recipientId: member.id,
        type: 'team_membership_changed',
        entityType: 'team',
        entityId: team.id,
        message: `You were added to team "${team.name}".`,
      })
      await notifyVaultOwnersOfMembershipChange(
        team.id,
        `${member.email} was added to team "${team.name}"`,
      )
      emitPermissionChange({ userIds: [member.id] })
      return { status: 'added' }
    },
  )

  app.delete<{ Params: { id: string; userId: string } }>(
    '/teams/:id/members/:userId',
    async (req, reply) => {
      if (!(await isTeamOwner(req.user!.id, req.params.id))) {
        return reply.code(403).send({ error: 'team owner required' })
      }
      const [removed] = await db
        .delete(teamMemberships)
        .where(
          and(
            eq(teamMemberships.teamId, req.params.id),
            eq(teamMemberships.userId, req.params.userId),
            eq(teamMemberships.role, 'member'),
          ),
        )
        .returning()
      if (!removed) return reply.code(404).send({ error: 'membership not found' })
      const team = (await db.select().from(teams).where(eq(teams.id, req.params.id)))[0]!
      const member = (await db.select().from(users).where(eq(users.id, req.params.userId)))[0]
      await notify({
        recipientId: req.params.userId,
        type: 'team_membership_changed',
        entityType: 'team',
        entityId: team.id,
        message: `You were removed from team "${team.name}".`,
      })
      await notifyVaultOwnersOfMembershipChange(
        team.id,
        `${member?.email ?? 'a user'} was removed from team "${team.name}"`,
      )
      emitPermissionChange({ userIds: [req.params.userId] })
      return { status: 'removed' }
    },
  )

  app.delete<{ Params: { id: string } }>('/teams/:id', async (req, reply) => {
    if (!(await isTeamOwner(req.user!.id, req.params.id))) {
      return reply.code(403).send({ error: 'team owner required' })
    }
    // Cascade per spec hardening: shares to this team must not dangle.
    const removed = await db
      .delete(vaultShares)
      .where(and(eq(vaultShares.granteeType, 'team'), eq(vaultShares.granteeId, req.params.id)))
      .returning({ vaultId: vaultShares.vaultId })
    await db.delete(teams).where(eq(teams.id, req.params.id))
    if (removed.length > 0) emitPermissionChange({ vaultIds: removed.map((r) => r.vaultId) })
    return { status: 'deleted' }
  })
}

import type { FastifyInstance } from 'fastify'
import { and, eq, isNull } from 'drizzle-orm'
import { db } from '../db/client.js'
import { mcpConnections, users } from '../db/schema.js'
import { generateToken, hashToken } from '../auth/tokens.js'
import { logSecurityEvent } from '../auth/security-events.js'
import { resolveAccess } from './permissions.js'
import { resolveRepositoryAccess } from '../repositories/permissions.js'

export function mcpConnectionRoutes(app: FastifyInstance) {
  app.addHook('preHandler', app.requireAuth)

  app.post<{
    Body: { name: string; scope: 'account' | 'vault' | 'repository'; vaultId?: string; repositoryId?: string }
  }>(
    '/mcp-connections',
    {
      schema: {
        body: {
          type: 'object',
          required: ['name', 'scope'],
          properties: {
            name: { type: 'string', minLength: 1, maxLength: 200 },
            scope: { enum: ['account', 'vault', 'repository'] },
            vaultId: { type: 'string', format: 'uuid' },
            repositoryId: { type: 'string', format: 'uuid' },
          },
        },
      },
    },
    async (req, reply) => {
      const { name, scope, vaultId, repositoryId } = req.body
      if (scope === 'vault') {
        if (!vaultId) return reply.code(400).send({ error: 'vaultId required for vault scope' })
        const access = await resolveAccess(req.user!.id, vaultId)
        if (!access) return reply.code(404).send({ error: 'vault not found' })
      }
      if (scope === 'repository') {
        if (!repositoryId) return reply.code(400).send({ error: 'repositoryId required for repository scope' })
        const access = await resolveRepositoryAccess(req.user!.id, repositoryId)
        if (!access) return reply.code(404).send({ error: 'repository not found' })
      }
      const token = generateToken()
      const [connection] = await db
        .insert(mcpConnections)
        .values({
          userId: req.user!.id,
          name,
          scope,
          vaultId: scope === 'vault' ? vaultId : null,
          repositoryId: scope === 'repository' ? repositoryId : null,
          tokenHash: hashToken(token),
        })
        .returning()
      await logSecurityEvent({
        type: 'mcp_connection_created',
        actorUserId: req.user!.id,
        mcpConnectionId: connection!.id,
        detail: { scope, vaultId, repositoryId },
      })
      // The raw token is returned exactly once and stored only as a hash.
      return { ...connectionView(connection!), token }
    },
  )

  app.get('/mcp-connections', async (req) => {
    const rows = await db
      .select()
      .from(mcpConnections)
      .where(eq(mcpConnections.userId, req.user!.id))
    return rows.map(connectionView)
  })

  app.post<{ Params: { id: string } }>('/mcp-connections/:id/revoke', async (req, reply) => {
    const [connection] = await db
      .update(mcpConnections)
      .set({ revokedAt: new Date() })
      .where(
        and(
          eq(mcpConnections.id, req.params.id),
          eq(mcpConnections.userId, req.user!.id),
          isNull(mcpConnections.revokedAt),
        ),
      )
      .returning()
    if (!connection) return reply.code(404).send({ error: 'connection not found' })
    await logSecurityEvent({
      type: 'mcp_connection_revoked',
      actorUserId: req.user!.id,
      mcpConnectionId: connection.id,
    })
    return { status: 'revoked' }
  })
}

function connectionView(c: typeof mcpConnections.$inferSelect) {
  return {
    id: c.id,
    name: c.name,
    scope: c.scope,
    vaultId: c.vaultId,
    repositoryId: c.repositoryId,
    createdAt: c.createdAt,
    lastUsedAt: c.lastUsedAt,
    expiresAt: c.expiresAt,
    revokedAt: c.revokedAt,
  }
}

export type McpAuth = {
  connection: typeof mcpConnections.$inferSelect
  user: typeof users.$inferSelect
}

/**
 * Resolves a bearer token to its connection + owning user, or null.
 * Live checks only (spec): revoked/expired connections and non-active
 * owners never resolve, regardless of when the token was issued.
 */
export async function resolveMcpToken(token: string): Promise<McpAuth | null> {
  const rows = await db
    .select({ connection: mcpConnections, user: users })
    .from(mcpConnections)
    .innerJoin(users, eq(users.id, mcpConnections.userId))
    .where(eq(mcpConnections.tokenHash, hashToken(token)))
    .limit(1)
  const row = rows[0]
  if (!row) return null
  const { connection, user } = row
  if (connection.revokedAt) return null
  if (connection.expiresAt && connection.expiresAt < new Date()) return null
  if (user.status !== 'active') return null
  await db
    .update(mcpConnections)
    .set({ lastUsedAt: new Date() })
    .where(eq(mcpConnections.id, connection.id))
  return { connection, user }
}

